import{_ as a,a0 as p,w as u,s as d,ao as n,I as l,x as s,a1 as t,A as i}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const H=JSON.parse('{"title":"用 Hugo 30 分钟搭建静态博客 | LCTT x X-CMD","titleTemplate":false,"description":"用 Hugo 30 分钟搭建静态博客 | LCTT (201809) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"用 Hugo 30 分钟搭建静态博客 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"用 Hugo 30 分钟搭建静态博客 | LCTT (201809) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201809/20180326 Start a blog in 30 minutes with Hugo, a static site generator written in Go","title":"用 Hugo 30 分钟搭建静态博客","tag":"201809","desc":""},"relativePath":"201809/20180326 Start a blog in 30 minutes with Hugo, a static site generator written in Go.md","filePath":"[post].md"}'),r={name:"201809/20180326 Start a blog in 30 minutes with Hugo, a static site generator written in Go.md"};function g(m,o,h,f,b,k){const e=p("Link");return u(),d("div",null,[o[49]||(o[49]=n('<h1 id="用-hugo-30-分钟搭建静态博客" tabindex="-1">用 Hugo 30 分钟搭建静态博客 <a class="header-anchor" href="#用-hugo-30-分钟搭建静态博客" aria-label="Permalink to “用 Hugo 30 分钟搭建静态博客”">​</a></h1><blockquote><p>了解 Hugo 如何使构建网站变得有趣。</p></blockquote><p><img src="https://opensource.com/sites/default/files/styles/image-full-size/public/lead-images/programming-code-keyboard-laptop-music-headphones.png?itok=EQZ2WKzy" alt=""></p><p>你是不是强烈地想搭建博客来将自己对软件框架等的探索学习成果分享呢？你是不是面对缺乏指导文档而一团糟的项目就有一种想去改变它的冲动呢？或者换个角度，你是不是十分期待能创建一个属于自己的个人博客网站呢？</p><p>很多人在想搭建博客之前都有一些严重的迟疑顾虑：感觉自己缺乏内容管理系统（CMS）的相关知识，更缺乏时间去学习这些知识。现在，如果我说不用花费大把的时间去学习 CMS 系统、学习如何创建一个静态网站、更不用操心如何去强化网站以防止它受到黑客攻击的问题，你就可以在 30 分钟之内创建一个博客？你信不信？利用 Hugo 工具，就可以实现这一切。</p><p><img src="https://opensource.com/sites/default/files/styles/panopoly_image_original/public/u128651/hugo_1.png?itok=JgxBSOBG" alt=""></p><p>Hugo 是一个基于 Go 语言开发的静态站点生成工具。也许你会问，为什么选择它？</p><ul><li>无需数据库、无需需要各种权限的插件、无需跑在服务器上的底层平台，更没有额外的安全问题。</li><li>都是静态站点，因此拥有轻量级、快速响应的服务性能。此外，所有的网页都是在部署的时候生成，所以服务器负载很小。</li><li>极易操作的版本控制。一些 CMS 平台使用它们自己的版本控制软件（VCS）或者在网页上集成 Git 工具。而 Hugo，所有的源文件都可以用你所选的 VCS 软件来管理。</li></ul><h3 id="_0-5-分钟-下载-hugo-生成一个网站" tabindex="-1">0-5 分钟：下载 Hugo，生成一个网站 <a class="header-anchor" href="#_0-5-分钟-下载-hugo-生成一个网站" aria-label="Permalink to “0-5 分钟：下载 Hugo，生成一个网站”">​</a></h3><p>直白的说，Hugo 使得写一个网站又一次变得有趣起来。让我们来个 30 分钟计时，搭建一个网站。</p><p>为了简化 Hugo 安装流程，这里直接使用 Hugo 可执行安装文件。</p>',11)),l("ol",null,[l("li",null,[l("p",null,[o[1]||(o[1]=s("下载和你操作系统匹配的 Hugo ",-1)),t(e,{href:"https://github.com/gohugoio/hugo/releases"},{default:i(()=>[...o[0]||(o[0]=[s("版本",-1)])]),_:1}),o[2]||(o[2]=s("；",-1))])]),o[9]||(o[9]=l("li",null,[l("p",null,[s("压缩包解压到指定路径，例如 windows 系统的 "),l("code",null,"C:\\hugo_dir"),s(" 或者 Linux 系统的 "),l("code",null,"~/hugo_dir"),s(" 目录；下文中的变量 "),l("code",null,"${HUGO_HOME}"),s(" 所指的路径就是这个安装目录；")])],-1)),o[10]||(o[10]=l("li",null,[l("p",null,[s("打开命令行终端，进入安装目录："),l("code",null,"cd ${HUGO_HOME}"),s("；")])],-1)),l("li",null,[o[8]||(o[8]=n("<p>确认 Hugo 已经启动：</p><ul><li>Unix 系统：<code>${HUGO_HOME}/[hugo version]</code>；</li><li>Windows 系统：<code>${HUGO_HOME}\\[hugo.exe version]</code>，例如：cmd 命令行中输入：<code>c:\\hugo_dir\\hugo version</code>。</li></ul><p>为了书写上的简化，下文中的 <code>hugo</code> 就是指 hugo 可执行文件所在的路径（包括可执行文件），例如命令 <code>hugo version</code> 就是指命令 <code>c:\\hugo_dir\\hugo version</code> 。(LCTT 译注：可以把 hugo 可执行文件所在的路径添加到系统环境变量下，这样就可以直接在终端中输入 <code>hugo version</code>）</p>",3)),l("p",null,[o[4]||(o[4]=s("如果命令 ",-1)),o[5]||(o[5]=l("code",null,"hugo version",-1)),o[6]||(o[6]=s(" 报错，你可能下载了错误的版本。当然，有很多种方法安装 Hugo，更多详细信息请查阅 ",-1)),t(e,{href:"https://gohugo.io/getting-started/installing/"},{default:i(()=>[...o[3]||(o[3]=[s("官方文档",-1)])]),_:1}),o[7]||(o[7]=s("。最稳妥的方法就是把 Hugo 可执行文件放在某个路径下，然后执行的时候带上路径名",-1))])]),o[11]||(o[11]=l("li",null,[l("p",null,[s("创建一个新的站点来作为你的博客，输入命令："),l("code",null,"hugo new site awesome-blog"),s("；")])],-1)),o[12]||(o[12]=l("li",null,[l("p",null,[s("进入新创建的路径下: "),l("code",null,"cd awesome-blog"),s("；")])],-1))]),o[50]||(o[50]=l("p",null,"恭喜你！你已经创建了自己的新博客。",-1)),o[51]||(o[51]=l("h3",{id:"_5-10-分钟-为博客设置主题",tabindex:"-1"},[s("5-10 分钟：为博客设置主题 "),l("a",{class:"header-anchor",href:"#_5-10-分钟-为博客设置主题","aria-label":"Permalink to “5-10 分钟：为博客设置主题”"},"​")],-1)),l("p",null,[o[14]||(o[14]=s("Hugo 中你可以自己构建博客的主题或者使用网上已经有的一些主题。这里选择 ",-1)),t(e,{href:"https://themes.gohugo.io/"},{default:i(()=>[...o[13]||(o[13]=[s("Kiera",-1)])]),_:1}),o[15]||(o[15]=s(" 主题，因为它简洁漂亮。按以下步骤来安装该主题：",-1))]),l("ol",null,[o[22]||(o[22]=l("li",null,[l("p",null,[s("进入主题所在目录："),l("code",null,"cd themes"),s("；")])],-1)),l("li",null,[o[21]||(o[21]=l("p",null,[s("克隆主题："),l("code",null,"git clone https://github.com/avianto/hugo-kiera kiera"),s("。如果你没有安装 Git 工具：")],-1)),l("ul",null,[l("li",null,[o[17]||(o[17]=s("从 ",-1)),t(e,{href:"https://github.com/avianto/hugo-kiera"},{default:i(()=>[...o[16]||(o[16]=[s("Github",-1)])]),_:1}),o[18]||(o[18]=s(" 上下载 hugo 的 .zip 格式的文件；",-1))]),o[19]||(o[19]=l("li",null,[s("解压该 .zip 文件到你的博客主题 "),l("code",null,"theme"),s(" 路径；")],-1)),o[20]||(o[20]=l("li",null,[s("重命名 "),l("code",null,"hugo-kiera-master"),s(" 为 "),l("code",null,"kiera"),s("；")],-1))])]),o[23]||(o[23]=n("<li><p>返回博客主路径：<code>cd awesome-blog</code>；</p></li><li><p>激活主题；通常来说，主题（包括 Kiera）都自带文件夹 <code>exampleSite</code>，里面存放了内容配置的示例文件。激活 Kiera 主题需要拷贝它提供的 <code>config.toml</code> 到你的博客下：</p><ul><li>Unix 系统：<code>cp themes/kiera/exampleSite/config.toml .</code>；</li><li>Windows 系统：<code>copy themes\\kiera\\exampleSite\\config.toml .</code>；</li><li>选择 <code>Yes</code> 来覆盖原有的 <code>config.toml</code>；</li></ul></li><li><p>（ 可选操作 ）你可以选择可视化的方式启动服务器来验证主题是否生效：<code>hugo server -D</code> 然后在浏览器中输入 <code>http://localhost:1313</code>。可用通过在终端中输入 <code>Crtl+C</code> 来停止服务器运行。现在你的博客还是空的，但这也给你留了写作的空间。它看起来如下所示：</p></li>",3))]),o[52]||(o[52]=l("p",null,[l("img",{src:"https://opensource.com/sites/default/files/styles/panopoly_image_original/public/u128651/hugo_2.png?itok=PINOIOSU",alt:""})],-1)),l("p",null,[o[25]||(o[25]=s("你已经成功的给博客设置了主题！你可以在官方 ",-1)),t(e,{href:"https://themes.gohugo.io/"},{default:i(()=>[...o[24]||(o[24]=[s("Hugo 主题",-1)])]),_:1}),o[26]||(o[26]=s(" 网站上找到上百种漂亮的主题供你使用。",-1))]),o[53]||(o[53]=n(`<h3 id="_10-20-分钟-给博客添加内容" tabindex="-1">10-20 分钟：给博客添加内容 <a class="header-anchor" href="#_10-20-分钟-给博客添加内容" aria-label="Permalink to “10-20 分钟：给博客添加内容”">​</a></h3><p>对于碗来说，它是空的时候用处最大，可以用来盛放东西；但对于博客来说不是这样，空博客几乎毫无用处。在这一步，你将会给博客添加内容。Hugo 和 Kiera 主题都为这个工作提供了方便性。按以下步骤来进行你的第一次提交：</p><ol><li><p>archetypes 将会是你的内容模板。</p></li><li><p>添加主题中的 archtypes 至你的博客：</p><ul><li>Unix 系统： <code>cp themes/kiera/archetypes/* archetypes/</code></li><li>Windows 系统：<code>copy themes\\kiera\\archetypes\\* archetypes\\</code></li><li>选择 <code>Yes</code> 来覆盖原来的 <code>default.md</code> 内容架构类型</li></ul></li><li><p>创建博客 posts 目录：</p><ul><li>Unix 系统： <code>mkdir content/posts</code></li><li>Windows 系统： <code>mkdir content\\posts</code></li></ul></li><li><p>利用 Hugo 生成你的 post：</p></li></ol><ul><li>Unix 系统：<code>hugo nes posts/first-post.md</code>;</li><li>Windows 系统：<code>hugo new posts\\first-post.md</code>;</li></ul><ol start="5"><li>在文本编辑器中打开这个新建的 post 文件：</li></ol><ul><li>Unix 系统：<code>gedit content/posts/first-post.md</code>；</li><li>Windows 系统：<code>notepadd content\\posts\\first-post.md</code>；</li></ul><p>此刻，你可以疯狂起来了。注意到你的提交文件中包括两个部分。第一部分是以 <code>+++</code> 符号分隔开的。它包括了提交文档的主要数据，例如名称、时间等。在 Hugo 中，这叫做前缀。在前缀之后，才是正文。下面编辑第一个提交文件内容：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>+++</span></span>
<span class="line"><span>title = &quot;First Post&quot;</span></span>
<span class="line"><span>date = 2018-03-03T13:23:10+01:00</span></span>
<span class="line"><span>draft = false</span></span>
<span class="line"><span>tags = [&quot;Getting started&quot;]</span></span>
<span class="line"><span>categories = []</span></span>
<span class="line"><span>+++</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Hello Hugo world! No more excuses for having no blog or documentation now!</span></span></code></pre></div><p>现在你要做的就是启动你的服务器：<code>hugo server -D</code>；然后打开浏览器，输入 <code>http://localhost:1313/</code>。</p><p><img src="https://opensource.com/sites/default/files/styles/panopoly_image_original/public/u128651/hugo_3.png?itok=I-_v0qLx" alt=""></p><h3 id="_20-30-分钟-调整网站" tabindex="-1">20-30 分钟：调整网站 <a class="header-anchor" href="#_20-30-分钟-调整网站" aria-label="Permalink to “20-30 分钟：调整网站”">​</a></h3><p>前面的工作很完美，但还有一些问题需要解决。例如，简单地命名你的站点：</p><ol><li>终端中按下 <code>Ctrl+C</code> 以停止服务器。</li><li>打开 <code>config.toml</code>,编辑博客的名称，版权，你的姓名，社交网站等等。</li></ol><p>当你再次启动服务器后，你会发现博客私人订制味道更浓了。不过，还少一个重要的基础内容：主菜单。快速的解决这个问题。返回 <code>config.toml</code> 文件，在末尾插入如下一段：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>[[menu.main]]</span></span>
<span class="line"><span>    name = &quot;Home&quot; #Name in the navigation bar</span></span>
<span class="line"><span>    weight = 10 #The larger the weight, the more on the right this item will be</span></span>
<span class="line"><span>    url = &quot;/&quot; #URL address</span></span>
<span class="line"><span>[[menu.main]]</span></span>
<span class="line"><span>    name = &quot;Posts&quot;</span></span>
<span class="line"><span>    weight = 20</span></span>
<span class="line"><span>    url = &quot;/posts/&quot;</span></span></code></pre></div><p>上面这段代码添加了 <code>Home</code> 和 <code>Posts</code> 到主菜单中。你还需要一个 <code>About</code> 页面。这次是创建一个 <code>.md</code> 文件，而不是编辑 <code>config.toml</code> 文件：</p><ol><li>创建 <code>about.md</code> 文件：<code>hugo new about.md</code> 。注意它是 <code>about.md</code>，不是 <code>posts/about.md</code>。该页面不是博客提交内容，所以你不想它显示到博客内容提交当中吧。</li><li>用文本编辑器打开该文件，输入如下一段：</li></ol><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>+++</span></span>
<span class="line"><span>title = &quot;About&quot;</span></span>
<span class="line"><span>date = 2018-03-03T13:50:49+01:00</span></span>
<span class="line"><span>menu = &quot;main&quot; #Display this page on the nav menu</span></span>
<span class="line"><span>weight = &quot;30&quot; #Right-most nav item</span></span>
<span class="line"><span>meta = &quot;false&quot; #Do not display tags or categories</span></span>
<span class="line"><span>+++</span></span>
<span class="line"><span></span></span>
<span class="line"><span>&gt; Waves are the practice of the water. Shunryu Suzuki</span></span></code></pre></div>`,18)),l("p",null,[o[29]||(o[29]=s("当你启动你的服务器并输入：",-1)),o[30]||(o[30]=l("code",null,"http://localhost:1313/",-1)),o[31]||(o[31]=s("，你将会看到你的博客。（访问我 Gihub 主页上的 ",-1)),t(e,{href:"https://m-czernek.github.io/awesome-blog/"},{default:i(()=>[...o[27]||(o[27]=[s("例子",-1)])]),_:1}),o[32]||(o[32]=s(" ）如果你想让文章的菜单栏和 Github 相似，给 ",-1)),o[33]||(o[33]=l("code",null,"themes/kiera/static/css/styles.css",-1)),o[34]||(o[34]=s(" 打上这个 ",-1)),t(e,{href:"https://github.com/avianto/hugo-kiera/pull/18/files"},{default:i(()=>[...o[28]||(o[28]=[s("补丁",-1)])]),_:1}),o[35]||(o[35]=s("。",-1))]),o[54]||(o[54]=l("hr",null,null,-1)),l("p",null,[o[37]||(o[37]=s("via: ",-1)),t(e,{href:"https://opensource.com/article/18/3/start-blog-30-minutes-hugo"},{default:i(()=>[...o[36]||(o[36]=[s("https://opensource.com/article/18/3/start-blog-30-minutes-hugo",-1)])]),_:1})]),l("p",null,[o[41]||(o[41]=s("作者：",-1)),t(e,{href:"https://opensource.com/users/mczernek"},{default:i(()=>[...o[38]||(o[38]=[s("Marek Czernek",-1)])]),_:1}),o[42]||(o[42]=s(" \u2028译者：",-1)),t(e,{href:"https://github.com/jrglinux"},{default:i(()=>[...o[39]||(o[39]=[s("jrg",-1)])]),_:1}),o[43]||(o[43]=s(" \u2028校对：",-1)),t(e,{href:"https://github.com/wxy"},{default:i(()=>[...o[40]||(o[40]=[s("wxy",-1)])]),_:1})]),l("p",null,[o[46]||(o[46]=s("本文由 ",-1)),t(e,{href:"https://github.com/LCTT/TranslateProject"},{default:i(()=>[...o[44]||(o[44]=[s("LCTT",-1)])]),_:1}),o[47]||(o[47]=s(" 原创编译，",-1)),t(e,{href:"https://linux.cn/"},{default:i(()=>[...o[45]||(o[45]=[s("Linux中国",-1)])]),_:1}),o[48]||(o[48]=s(" 荣誉推出",-1))])])}const C=a(r,[["render",g]]);export{H as __pageData,C as default};
